import numpy as np

def algorithm(func, dim, lb, ub, budget, rng):
    best = np.zeros(dim)
    best_f = float('inf')

    for _ in range(budget):
        candidate = rng.uniform(lb, ub, size=dim)
        f_value = func(candidate)

        if f_value < best_f:
            best_f = f_value
            best = candidate

    return np.clip(best, lb, ub)
